targets.query:
import "influxdata/influxdb/schema"
import "date"

getOrDefault = (f, d) => if exists f then f else d

// Constants
days_observed = 60
total_days_in_year = 365
scaling_factor = float(v: total_days_in_year) / float(v: days_observed)  // 6.083333

// Step 1: Query Total Cost
data_total = from(bucket: "default_agg_kpi")
  |> range(start: -60d)
  |> filter(fn: (r) => r._field == "cost")
  |> group()  // Group without specific columns to keep it simple
  |> sum(column: "_value")
  |> map(fn: (r) => ({
      _key: "combined",  // Add a key for joining
      total_predicted_cost: r._value * scaling_factor
  }))

// Step 2: Query Project-Specific Cost
data_project = from(bucket: "default_agg_kpi")
  |> range(start: -60d)
  |> filter(fn: (r) => r._field == "cost" and r.user_hash == "undefined")
  |> group()
  |> sum(column: "_value")
  |> map(fn: (r) => ({
      _key: "combined",  // Add the same key for joining
      project_predicted_cost: r._value * scaling_factor
  }))

// Step 3: Join and Calculate the Difference
difference_data = join(
  tables: {total: data_total, project: data_project},
  on: ["_key"],  // Join on the common key
)
|> map(fn: (r) => ({
    total_predicted_cost: r.total_predicted_cost,
    project_predicted_cost: r.project_predicted_cost,
    difference: r.total_predicted_cost - r.project_predicted_cost
}))

// Output the Difference
difference_data
|> group()
